bool DraftData(const base::DictValue& value, std::string_view origin) {
  if (value.size() != 5 || !Text(value, "format", "aux.ui-draft-capture.v1") ||
      !Text(value, "origin", origin)) return false;
  const auto* session = value.FindDict("sessionEntries"), *local = value.FindDict("localEntries");
  const auto* mutations = value.FindList("mutations");
  if (!session || !local || !mutations || session->size() + local->size() + mutations->size() > 4096) return false;
  for (const auto* entries : {session, local}) for (const auto [key, raw] : *entries)
