    if (!key || (!Text(*mutation, "storage", "local-storage") && !Text(*mutation, "storage", "session-storage")) ||
        !UiDraftKey(*key, Text(*mutation, "storage", "local-storage"))) return false;
    if (Text(*mutation, "operation", "remove")) { if (mutation->size() != 3) return false; }
    else if (Text(*mutation, "operation", "set")) {
