        (!mutation.remove && !ReadWireUnits(change->Find("value"), mutation.value, total)) ||
        !changed.emplace(mutation.local, mutation.key).second) return std::nullopt;
    stores.mutations.push_back(std::move(mutation));
  }
  return stores;
}

